import {addClue,tick,finish,DEDUCTIONS} from './engine.mjs';
export const AREAS={
 study:{name:'221B Baker Street',label:'Baker Street',atlas:'london.webp',tile:0,weather:'dust',desc:'Feuer im Kamin. Regen am Fenster.',spots:[['desk',.32,.55,'Der Schreibtisch','book'],['watson',.7,.61,'Watson','person'],['leave',.5,.25,'Zum Theater','door']]},
 theatre:{name:'Das Lyceum-Theater',label:'Theater',atlas:'theatre.webp',tile:0,weather:'dust',desc:'Die Vorstellung ist unterbrochen.',spots:[['beaumont',.29,.58,'Direktor Beaumont','person'],['keylog',.74,.58,'Die Portiersloge','book'],['rook',.52,.3,'Victor Rook','person']]},
 dressing:{name:'Claras Garderobe',label:'Garderobe',atlas:'theatre.webp',tile:1,weather:'dust',desc:'Das Licht am Spiegel brennt noch.',spots:[['ticket',.28,.56,'Der Schminktisch','search'],['grease',.69,.39,'Die Seitentür','search'],['contract',.65,.68,'Der Papierkorb','book']]},
 backstage:{name:'Hinter dem Vorhang',label:'Hinterbühne',atlas:'theatre.webp',tile:2,weather:'dust',desc:'Seile knarren über der leeren Bühne.',spots:[['mercer',.27,.59,'Eli Mercer','person'],['plan',.67,.4,'Der Bühnenplan','book'],['rag',.68,.69,'Die Kostümkiste','search']]},
 alley:{name:'Der Lieferhof',label:'Lieferhof',atlas:'theatre.webp',tile:3,weather:'rain',desc:'Regen sammelt sich zwischen den Pflastersteinen.',spots:[['agnes',.28,.61,'Agnes Ward','person'],['delivery',.69,.58,'Der Lieferzettel','book'],['chase',.51,.29,'Ein Mann am Tor','search']]},
 station:{name:'Der Bahnhof',label:'Bahnhof',atlas:'london.webp',tile:1,weather:'steam',desc:'Dampf treibt unter das Glasdach.',spots:[['station',.32,.56,'Die Gepäckausgabe','person'],['platform',.68,.4,'Bahnsteig nach Dover','search']]},
 printer:{name:'Druckerei Bell',label:'Druckerei',atlas:'london.webp',tile:2,weather:'dust',desc:'Druckerschwärze und warmes Papier.',spots:[['printer',.28,.57,'Mrs Bell','person'],['ledger',.69,.53,'Das Auftragsbuch','book']]},
 trap:{name:'Unter der Bühne',label:'Wartungskammer',atlas:'london.webp',tile:3,weather:'dust',desc:'Ein leises Klopfen hinter Holz.',spots:[['hatch',.5,.39,'Die verschlossene Kammer','door'],['clara',.7,.65,'Hinter der Wand','person']]}
};
const choice=(label,next,extra={})=>({label,next,...extra});
const close=choice('Weiter ermitteln',null);
const node=(pages,choices=[close],speaker='')=>({pages:Array.isArray(pages)?pages:[pages],choices,speaker});
export function objective(s){if(s.ending)return 'Fall abgeschlossen';if(!s.flags.arrival)return 'Erfahre im Theater, was mit Clara Vale geschehen ist.';if(!s.clues.includes('grease')||!s.clues.includes('plan'))return 'Untersuche Garderobe und Hinterbühne.';if(!s.deductions.includes('route'))return 'Verbinde in der Fallakte die Spuren zu Claras Weg.';if(!s.flags.rescued)return 'Die Spur führt unter die Bühne. Clara könnte noch dort sein.';if(!s.deductions.includes('opportunity')||!s.deductions.includes('motive'))return 'Clara ist sicher. Wer hatte Zugang – und ein Motiv?';return 'Prüfe deine Beweise und schließe den Fall in der Fallakte ab.';}
export function getNode(s,id){const f=s.flags,has=k=>s.clues.includes(k);const N={
 intro:()=>node([
 'London, 9. November 1888.\n\nDer Regen hat den Abendverkehr zum Schweigen gebracht. Sie sitzen am Fenster der Baker Street, als Mrs Hudson einen durchnässten Jungen hereinführt. Er hält ein Telegramm so fest, dass seine Finger weiß geworden sind.',
 '„Für Mr Holmes. Vom Lyceum.“\n\nAuf dem Papier steht: „Clara Vale verschwunden. Vorstellung abgebrochen. Bitte sofort kommen. Keine Polizei vor Ihrer Ankunft. Beaumont.“\n\nWatson legt seine Zeitung beiseite. „Die Schauspielerin? Sie sollte heute vor vollem Haus auftreten.“',
 'Sie kennen weder Clara Vale noch den Grund ihres Verschwindens. Aber der letzte Satz des Telegramms fällt Ihnen auf. Jemand möchte Hilfe – und fürchtet zugleich, was sie ans Licht bringen könnte.\n\nSie nehmen Mantel und Lupe. Watson greift nach seiner Arzttasche. Die Ermittlungen beginnen um 21:15 Uhr; die Anfahrt ist darin bereits berücksichtigt.'
 ],[choice('Mit Watson zum Theater fahren','arrival',{flags:['intro'],area:'theatre'})]),
 arrival:()=>node(['Im Foyer warten Zuschauer unter halb erloschenen Gaslampen. Niemand weiß, ob er nach Hause gehen soll. Direktor Beaumont kommt Ihnen entgegen. Seine Manschette ist eingerissen.\n\n„Miss Vale kam um fünf vor neun in ihre Garderobe. Zehn Minuten später war sie fort. Niemand hat sie hinausgehen sehen.“',
 '„Wer war in ihrer Nähe?“\n\n„Unser Verwalter Rook. Der Bühnenmeister Mercer. Agnes, die Näherin. Es gab Streit über Geld, aber das ist im Theater nichts Ungewöhnliches.“\n\nWatson schaut zur Bühne. „Dann sollten wir zuerst herausfinden, ob sie überhaupt gegangen ist.“',
 'Beaumont senkt die Stimme. „Rook lässt um Viertel vor elf die Kassenunterlagen ins Hauptbüro bringen. Danach reist er zum Eigentümer. Falls Sie ihn sprechen müssen, tun Sie es vorher.“\n\nSie lassen sich den Weg zur Garderobe zeigen. Die Schauspielerin hat einen Namen, einen letzten bekannten Aufenthaltsort und zehn fehlende Minuten. Damit lässt sich arbeiten.'
 ],[choice('Mit der Untersuchung beginnen',null,{flags:['arrival','beaumont']})]),
 desk:()=>node('Auf Ihrem Schreibtisch liegt das Telegramm aus dem Lyceum. Sie können hier in Ruhe die Beweise ordnen. Die Zeit verstreicht erst, wenn Sie reisen oder eine aufwendige Handlung ausführen.',[choice('Die Fallakte öffnen','@case'),choice('Zum Theater fahren','arrival',{area:'theatre'}),close]),
 leave:()=>node('Draußen wartet eine Droschke. Watson nimmt neben Ihnen Platz.',[choice('Zum Lyceum',s.flags.arrival?null:'arrival',{area:'theatre'}),close]),
 watson:()=>node(watsonHint(s),[close],'Dr. Watson'),
 beaumont:()=>node(f.beaumont&&has('contract')?'Sie zeigen Beaumont den zerrissenen Vertrag. Er liest die Randnotiz und wird still.\n\n„Die Wohltätigkeitsabende organisiert Rook. Ich sehe die endgültigen Summen erst beim Jahresabschluss.“\n\n„Sie haben sich nicht dafür interessiert?“\n\n„Das“, sagt er nach einer Pause, „ist womöglich eine sehr schlechte Verteidigung. Aber es ist die Wahrheit.“':'„Clara und ich haben gestritten“, sagt Beaumont. „Über ihren Vertrag für die nächste Spielzeit. Ich wollte, dass sie bleibt. Sie wollte erst die Abrechnungen sehen.“\n\nEr zeigt auf das Publikum. „Zwischen fünf vor neun und Viertel nach neun stand ich hier vorne. Fragen Sie die Leute.“\n\nSie befragen zwei unabhängig wartende Zuschauer. Beide erinnern sich an Beaumonts vergeblichen Versuch, das Publikum zu beruhigen. Seine Darstellung wird für dieses Zeitfenster bestätigt.“',[close]),
 rook:()=>f.late?node('Rooks Platz ist leer. Er hat das Theater um Viertel vor elf verlassen, wie angekündigt. Der Portier hat seine Abfahrt notiert. Sie können weiterhin Beweise sichern und Lestrade verständigen.',[close]):node(f.rook?'„Sie kennen meine Aussage“, sagt Rook. „Bis zehn nach neun beim Fuhrmann, danach auf der Bühne.“\n\nEr schließt sein Notizbuch. „Um Viertel vor elf bin ich fort. Wenn Sie etwas gegen mich vorzubringen haben, brauchen Sie mehr als einen misstrauischen Blick.“':'Victor Rook trägt einen sorgfältig gebürsteten Anzug. „Clara ist ehrgeizig. Vielleicht hat sie ein besseres Angebot bekommen.“\n\nSie fragen nach der Zeit ihres Verschwindens.\n\n„Von zwanzig vor neun bis zehn nach neun war ich mit dem Fuhrmann im Hof. Dann hörte ich von der Aufregung.“\n\nEr antwortet zu schnell auf eine Frage, die Sie noch nicht gestellt haben: „Mit ihren persönlichen Papieren habe ich nichts zu tun.“',[choice('Seine Aussage notieren',null,{flags:['rook'],cost:1}),...(s.deductions.includes('opportunity')?[choice('Ihn mit der Lücke im Alibi konfrontieren','rookConfront')]:[]),close]),
 rookConfront:()=>node('Sie nennen die Abfahrtszeit auf dem Lieferzettel. Rook schaut nicht auf den Zettel, sondern auf die Tür.\n\n„Dann habe ich mich in der Zeit geirrt.“\n\n„Um zwanzig Minuten?“\n\n„Es war ein hektischer Abend.“\n\nEr gibt Ihnen keine neue Erklärung. Seine Unruhe ist kein Geständnis. Für eine belastbare Beschuldigung müssen Zugang, Gelegenheit und Motiv zusammenpassen.',[close]),
 keylog:()=>has('keylog')?node('Die Eintragung bleibt eindeutig: Rook holte den einzigen Wartungsschlüssel um 20:45. Er wurde nicht zurückgegeben. Ein Ersatz ist beim Bühnenmeister versiegelt.',[choice('Register ansehen','@clue:keylog'),close]):node('Der Portier schlägt ein schmales Register auf. „Alle Schlüssel werden eingetragen. Rook nahm den Wartungsschlüssel um Viertel vor neun. Hier steht es.“\n\nSie fahren mit dem Finger die leere Rückgabespalte entlang.\n\n„Ersatz?“\n\n„Beim Bühnenmeister, unter Siegel. Ich habe es heute Mittag selbst geprüft.“',[choice('Die Schlüsselausgabe abschreiben',null,{clue:'keylog',cost:1})]),
 ticket:()=>has('ticket')?node('Die lose Fahrkarte liegt in Ihrer Beweismappe. Sie führt zum Bahnhof – aber noch beweist sie keine Reise.',[choice('Fahrkarte ansehen','@clue:ticket'),close]):node('Auf dem Schminktisch liegt eine Fahrkarte nach Dover. Daneben ist ein Glas Wasser umgestürzt; unter dem Spiegel liegt jedoch kein gepackter Koffer.\n\nAuf die Rückseite hat jemand „C. Vale · 17“ geschrieben. Die violette Tinte glänzt noch.\n\nWatson sieht zur Tür. „Wenn sie fortwollte, war sie in Eile. Oder jemand möchte, dass wir genau das glauben.“',[choice('Die Fahrkarte sichern',null,{clue:'ticket',cost:1})]),
 grease:()=>has('grease')?node('Der Schleifstreifen führt von der Garderobe durch die Seitentür. Die blaue Schmiere daran stimmt mit Ihrer Probe überein.',[choice('Die Probe ansehen','@clue:grease'),close]):node('Sie gehen vor der Seitentür in die Hocke. Am unteren Rahmen haftet etwas Blaues. Daneben liegt ein Faden weinroter Seide.\n\nIm schrägen Spiegellicht erkennen Sie eine schmale Schleifspur. Hier wurde etwas Schweres durch die Tür gezogen. Sie können die Spur vorsichtig untersuchen oder erst den Bühnenplan suchen.',[choice('Die frische Spur untersuchen','greaseResult',{test:{skill:'observe',dc:12},event:'grease',cost:1}),close]),
 greaseResult:()=>node(s.lastSuccess?'In der Schmiere sitzen feine Messingspäne. Sie nehmen eine Probe und folgen dem Streifen bis zur Schwelle. Clara trug heute ein weinrotes Bühnenkleid.\n\nDie Spur führt nach innen, hinter die Kulissen. Wer die Fahrkarte gelegt hat, könnte Sie in die Gegenrichtung schicken.':'Im dunklen Gang verlieren Sie den Verlauf der Spur. Sie brauchen eine Lampe und untersuchen den Rahmen erneut. Das kostet fünf weitere Minuten, aber die blaue Schmiere lässt sich jetzt sicher abnehmen.\n\nSie wissen noch nicht, woher sie stammt. Ein Plan oder der Bühnenmeister könnte helfen.',[close]),
 contract:()=>has('contract')?node('Die beiden Hälften des Vertrags liegen in Ihrer Mappe. Clara hat eine Bestätigung der Stiftung verlangt und die Unterschrift verweigert.',[choice('Vertrag ansehen','@clue:contract'),close]):node('Im Papierkorb finden Sie zwei Hälften eines Vertrags. Es geht nicht um Claras Gage, sondern um die Abrechnung der Wohltätigkeitsvorstellungen.\n\nAn der Unterschriftszeile steht: „Erst wenn die Stiftung die wirkliche Summe bestätigt.“\n\nDie Druckermarke lautet „Bell, Fleet Street“. Auf dem Rand hat Clara „Durchschlag erbeten“ notiert. Wenn sie Zahlen überprüfen ließ, könnte dort noch etwas liegen.',[choice('Den Vertrag zusammensetzen und sichern',null,{clue:'contract',cost:1})]),
 mercer:()=>node(f.mercer?'Mercer wartet an seiner Werkbank. „Wenn Sie den Ersatz brauchen: Das Siegel ist noch ganz.“\n\nEr zeigt auf die geschlossene Kassette. Sein eigener Schlüssel passt nur zur Werkstatt.': 'Eli Mercer ist kräftig, übermüdet und sichtlich aufgebracht. „Ja, ich fahre nach Dover. Nach dem Abbau. Meine Schwester erwartet mich.“\n\nEr klopft auf seine Werkzeugkiste. „Gepäcknummer siebzehn. Was hat das mit Clara zu tun?“\n\nSie fragen nach der Wartung. „Rook hat den Schlüssel. Mein Ersatz liegt hier versiegelt. Die blaue Schmiere benutzen wir nur am Schlitten unter der Bühne.“',[choice('Mit ihm die Werkstatt prüfen',null,{flags:['mercer'],cost:f.mercer?0:1}),...(s.deductions.includes('route')?[choice('Den versiegelten Ersatzschlüssel holen','spare',{event:'spare',cost:1})]:[]),close]),
 spare:()=>node('Mercer bricht das unversehrte Siegel vor Ihren Augen und reicht Ihnen den Ersatzschlüssel.\n\n„Die Wartungsluke liegt hinter dem Waldprospekt“, sagt er. „Dahinter ist die Kammer. Wenn dort jemand ist, hören Sie ihn durch die Wand.“\n\nDamit haben Sie einen sicheren Zugang. Ein Schloss aufzubrechen ist nicht nötig.',[close]),
 plan:()=>has('plan')?node('Der Plan führt von der Garderobentür über den Kulissengang zur Wartungsluke. Blau markiert ist nur der Schlitten unter der Bühne.',[choice('Plan ansehen','@clue:plan'),close]):node('An der Wand hängt ein abgegriffener Bühnenplan. Rote Linien kennzeichnen die öffentliche Bühne, blaue den Wartungsschlitten darunter.\n\nEine Seitentür der Garderobe führt direkt zur Wartungsluke. Sie liegt hinter dem Waldprospekt.\n\nSie zeichnen den Verlauf ab. In Verbindung mit einer passenden Spur ließe sich damit prüfen, ob Clara diesen Weg genommen hat.',[choice('Den Plan abzeichnen',null,{clue:'plan',cost:1})]),
 rag:()=>has('rag')?node('Watson hat das Tuch sicher verpackt. Der Geruch deutet auf eine Betäubung, verrät aber nicht, wer das Mittel benutzt hat.',[choice('Watsons Befund ansehen','@clue:rag'),close]):node('Hinter der Kostümkiste liegt ein gefaltetes Tuch. Watson hält Sie zurück, bevor Sie es dicht ans Gesicht nehmen.\n\n„Chloroform, vermutlich. Nicht weiter einatmen.“\n\nAn der Naht hängt weinrote Seide. Sie lassen ihn das Tuch einpacken. Eine Untersuchung im Labor wäre genauer, aber die Zeit ist jetzt wichtiger: Clara könnte medizinische Hilfe brauchen.',[choice('Das Tuch als Beweis sichern',null,{clue:'rag',cost:1})]),
 agnes:()=>node(f.agnes?'Agnes zieht ihren Schal fester. „Die Druckerei Bell. Clara sagte, die Zahlen würden nicht zusammenpassen. Mehr weiß ich wirklich nicht.“':'Agnes Ward wartet unter einem Vordach. „Clara schickte mich am Nachmittag zu Mrs Bell in der Fleet Street. Wegen einer Abrechnung.“\n\n„Hat Clara Angst gehabt?“\n\n„Sie war wütend. Sie sagte, sie würde ihren Namen nicht unter eine Lüge setzen.“\n\nAgnes sah den Lieferwagen um zehn vor neun abfahren. Wer danach noch im Hof war, kann sie nicht sagen.',[choice('Die Adresse der Druckerei notieren',null,{flags:['agnes'],cost:f.agnes?0:1}),close]),
 delivery:()=>has('delivery')?node('Der Lieferzettel nennt 20:50 als Abfahrt. Das widerspricht einem Aufenthalt mit dem Fuhrmann bis 21:10.',[choice('Lieferzettel ansehen','@clue:delivery'),close]):node('Unter dem Klemmbrett des Pförtners steckt der Lieferzettel. Die Tinte ist verlaufen, aber die Uhrzeit bleibt lesbar: „abgeladen und abgefahren: 20:50“. Darunter Rooks Quittierung.\n\nAgnes schaut Ihnen über die Schulter. „Ja. Dann war der Wagen fort. Rook hat vorhin gegenüber dem Portier behauptet, er sei bis zehn nach neun beim Fuhrmann gewesen. Das stimmt nicht.“',[choice('Den quittierten Zettel sichern',null,{clue:'delivery',cost:1})]),
 chase:()=>f.chase?node('Am Tor ist niemand mehr. Die regennassen Spuren führen auf die Straße und verlieren sich zwischen den Droschken.',[close]):node('Ein Mann im grauen Mantel drückt sich am Tor vorbei. Als er Ihre Lupe sieht, beschleunigt er seinen Schritt. Unter seinem Arm steckt ein Umschlag mit der Marke der Druckerei Bell.\n\nSie können ihm folgen. Aber wer flieht, ist nicht zwangsläufig der Entführer – und die Verfolgung kostet Zeit.',[choice('Dem Mann unauffällig folgen','chaseResult',{test:{skill:'dexterity',dc:14},event:'chase',cost:2}),choice('Bei den gesicherten Spuren bleiben',null)]),
 chaseResult:()=>node(s.lastSuccess?'Sie holen ihn an der nächsten Ecke ein. Der Mann hebt sofort die Hände. „Ich bin nur Bote! Für Rook, von Bell.“\n\nDer Umschlag enthält eine harmlose Theaterrechnung. Doch er bestätigt Ihnen die Adresse der Druckerei und erzählt, dass Clara dort einen Durchschlag bestellt hat. Sie lassen ihn gehen.':'Der Mann verschwindet zwischen zwei Droschken. Sie kehren durchnässt zum Theater zurück.\n\nWatson wartet am Tor. „Sein Umschlag trug Bells Marke. Die Druckerei können wir auch ohne ihn aufsuchen.“\n\nEine verpasste Verfolgung ist kein verlorener Fall.',[close]),
 station:()=>has('station')?node('Der Gepäckbeamte bleibt bei seiner Auskunft. Nummer 17 gehört zu Mercers Werkzeugkiste. Keine Aufgabe auf Claras Namen.',[choice('Auskunft ansehen','@clue:station'),close]):node('Der Gepäckbeamte prüft Ihr Ticket und dann sein Buch. „Siebzehn ist eine Werkzeugkiste. Eli Mercer. Die Nummer auf dieser Fahrkarte hat jemand selbst dazugeschrieben.“\n\nEine Frau namens Clara Vale hat kein Gepäck aufgegeben. Den Kauf der losen Karte kann der Beamte keiner Person zuordnen.\n\nSie haben Zeit verloren, aber eine wichtige Grenze erkannt: Die Karte beweist keine Flucht.',[choice('Die Auskunft notieren',null,{clue:'station',flags:['stationVisit'],cost:1})]),
 platform:()=>node('Der Zug nach Dover steht unter Dampf. Ein Schaffner schüttelt den Kopf, als Sie Clara beschreiben. Er hat sie nicht gesehen, kann aber auch nicht jeden Reisenden überwacht haben.\n\nWatson blickt zur Uhr. „Wir sollten eine fehlende Beobachtung nicht mit einem Beweis verwechseln.“',[choice('Zum Theater zurückkehren',null,{area:'theatre'}),close]),
 printer:()=>node(has('ledger')?'Mrs Bell hat Ihnen den Durchschlag überlassen. „Clara wollte, dass jemand hinsieht“, sagt sie. „Tun Sie das bitte ordentlich.“':'Mrs Bell lässt die Presse auslaufen. „Clara bat mich, die beiden Abrechnungen zu vergleichen. Rook sagte später, es sei ein Druckfehler und ich solle den Durchschlag vernichten.“\n\n„Haben Sie?“\n\n„Ich vernichte nichts, bevor es bezahlt ist.“ Sie deutet auf das Auftragsbuch. „Wenn Sie ihn brauchen, erkläre ich Ihnen auch jede Zahl darin.“',[choice('Das Auftragsbuch untersuchen','ledger'),close]),
 ledger:()=>has('ledger')?node('Die Summen stimmen nicht überein: 240 Pfund Einnahmen, 80 Pfund an die Stiftung gemeldet. Rook quittierte den Empfang.',[choice('Die Abrechnung ansehen','@clue:ledger'),close]):node('Mrs Bell legt zwei Durchschläge nebeneinander. Der erste nennt 240 Pfund Einnahmen aus den Wohltätigkeitsabenden. Der zweite, für die Stiftung, nur 80.\n\nAuf dem internen Blatt hat Rook den Empfang der 240 Pfund unterschrieben. Clara sollte später die kleinere Summe bestätigen.\n\n„Sie können mich als Zeugin nennen“, sagt Mrs Bell. „Dafür brauchen Sie keine Vermutung.“',[choice('Den Durchschlag mit Bells Bestätigung sichern',null,{clue:'ledger',flags:['printVisit'],cost:1})]),
 hatch:()=>f.rescued?node('Die Kammertür steht offen. Watson hat Clara ins Foyer gebracht. Sie ist erschöpft, aber außer Gefahr.',[close]):f.lock?node('Sie setzen den Ersatzschlüssel ein. Von der anderen Seite hören Sie ein Kratzen.\n\n„Miss Vale? Sherlock Holmes. Treten Sie von der Tür zurück.“',[choice('Die Kammer öffnen und Clara befreien','rescue',{event:'rescue',cost:1})]):node('Hinter der verschlossenen Tür klopft jemand dreimal. Dann hören Sie eine schwache Stimme.\n\nSie könnten das alte Schloss mit Ihrem Werkzeug öffnen. Der versiegelte Ersatz beim Bühnenmeister wäre der sichere Weg.',[choice('Das Schloss vorsichtig öffnen','lockResult',{test:{skill:'dexterity',dc:13},event:'lock',cost:1,disabled:f.lockFailed}),choice('Den Ersatz beim Bühnenmeister holen',null,{area:'backstage'}),close]),
 lockResult:()=>node(s.lastSuccess?'Der Riegel springt zurück. Sie fangen die schwere Tür ab, bevor sie gegen die Wand schlägt. Im Dunkeln sitzt eine Frau im weinroten Bühnenkleid.':'Das Werkzeug verkantet. Sie ziehen es vorsichtig heraus, bevor es abbricht. Noch einmal sollten Sie es nicht versuchen.\n\n„Ich hole den Ersatzschlüssel“, sagen Sie durch die Tür. Die Frau antwortet mit einem leisen Klopfen.',s.lastSuccess?[choice('Clara zu Watson bringen','rescue',{event:'rescue'})]:[choice('Zum Bühnenmeister zurück',null,{area:'backstage'})]),
 clara:()=>f.rescued?node('Clara wird oben von Watson betreut. Ihre Aussage liegt in Ihrer Fallakte. Sie kann den Täter nicht sicher erkennen; das müssen die übrigen Beweise leisten.',[choice('Claras Aussage ansehen','@clue:clara'),close]):node('Eine Hand kratzt schwach an der Holzwand. „Ist da jemand?“\n\n„Ja“, antworten Sie. „Wir öffnen die Tür.“\n\nSie treten zur Kammer zurück.',[choice('Die Kammertür untersuchen','hatch')]),
 rescue:()=>node(['Watson kniet neben Clara und prüft ihren Puls. Sie braucht frische Luft und Ruhe. Dann trägt er sie mit Mercers Hilfe die Stufen hinauf.\n\nSie bleiben einen Moment in der Kammer stehen. Auf dem Boden liegt ein abgerissener Seidenfaden. Der Weg der Spur endet hier.',
 'Oben spricht Clara langsam. „Jemand kam von der Seite. Ich sollte die Abrechnung unterschreiben. Ich weigerte mich. Danach weiß ich fast nichts mehr.“\n\n„Haben Sie ihn erkannt?“\n\nSie schüttelt den Kopf. „Ich möchte keinen Namen nennen, nur weil Sie ihn erwarten.“\n\nSie notieren genau das. Clara ist gerettet. Der Täter ist damit noch nicht bewiesen.'
 ],[choice('Die Ermittlung fortsetzen',null)]),
 epilogue:()=>node(ending(s),[choice('Fallakte lesen','@case'),choice('Ergebnis sichern','@export'),choice('Zur Fallauswahl','@title')])
};return (N[id]||(()=>node('Sie sehen sich aufmerksam um. Der nächste Schritt liegt bei Ihnen.',[close])))();}
export function apply(s,c,result=null){if(s.ending)return 'epilogue';if(c.disabled)throw Error('Diese Handlung ist nicht möglich.');if(c.cost)tick(s,c.cost);for(const k of c.flags||[])s.flags[k]=true;if(c.clue)addClue(s,c.clue);if(result){s.lastSuccess=result.success;s.rolls.push(`${result.value} + ${result.bonus} = ${result.total} · Ziel ${result.dc} · ${result.success?'gelungen':'misslungen'}`);s.rolls=s.rolls.slice(-20);}
if(c.event==='grease'){addClue(s,'grease');if(!result.success)tick(s);}
if(c.event==='chase'){s.flags.chase=true;s.flags.chaseWon=!!result.success;s.flags.printerLead=true;}
if(c.event==='spare')s.flags.lock=true;
if(c.event==='lock'){if(result.success)s.flags.lock=true;else s.flags.lockFailed=true;}
if(c.event==='rescue'){if(!s.flags.lock||!s.deductions.includes('route'))throw Error('Die Kammer ist noch verschlossen.');s.flags.rescued=true;addClue(s,'clara');s.area='theatre';s.pos={x:.5,y:.78};}
if(c.area){if(c.area!==s.area&&!c.flags?.includes('intro'))tick(s);s.area=c.area;s.pos={x:.5,y:.78};if(c.area==='theatre'&&!s.flags.arrival)s.node='arrival';}
s.node=c.next;s.page=0;return c.next;}
export function watsonHint(s){if(!s.flags.arrival)return '„Beginnen wir beim letzten sicheren Punkt: Clara wurde in ihrer Garderobe gesehen. Alles andere müssen wir erst feststellen.“';if(!s.clues.includes('grease'))return '„Die Fahrkarte ist auffällig. Aber eine Reise hinterlässt mehr als ein Stück Papier. Untersuchen wir auch den Weg aus dem Zimmer.“';if(!s.clues.includes('plan'))return '„Wir haben die blaue Schmiere. Uns fehlt, wo sie im Theater verwendet wird. Hinter der Bühne dürfte es einen Plan geben.“';if(!s.deductions.includes('route'))return '„Nehmen Sie in der Fallakte die blaue Schmiere und den Bühnenplan zusammen. Welche Verbindung können beide gemeinsam belegen?“';if(!s.flags.rescued)return '„Der Weg zur Wartungskammer ist jetzt auf der Karte markiert. Wenn Clara dort ist, hat ihre Rettung Vorrang.“';if(!s.clues.includes('keylog')||!s.clues.includes('delivery'))return '„Ein Alibi besteht aus Orten und Zeiten. Vergleichen Sie das Schlüsselregister im Theater mit dem Lieferzettel im Hof.“';if(!s.clues.includes('ledger'))return '„Der Vertrag erklärt den Streit noch nicht. Die Druckerei Bell könnte die tatsächlichen Summen kennen.“';if(s.deductions.length<3)return '„Ordnen Sie in der Fallakte Zugang und Zeitfenster sowie Vertrag und Abrechnung. Dann prüfen wir, was die Beweise tatsächlich tragen.“';return '„Wir haben den Weg, das Zeitfenster und den Grund. Die letzte Entscheidung liegt bei Ihnen. Ich werde Ihnen keinen Namen vorsagen.“';}
export function ending(s){const tails={
 complete:['Lestrade hört zu, ohne Sie zu unterbrechen. Dann legen Sie die Schlüsselausgabe, den Lieferzettel und Bells bestätigte Abrechnung auf den Tisch. Jede Behauptung hat einen Beleg. Rooks versuchte Erklärung scheitert an den Zeiten.','Rook wird noch im Theater festgenommen. Clara bleibt bei Watson, bis ihr Zittern nachlässt. „Sie haben mich nicht nur gefunden“, sagt sie. „Sie haben mir zugehört.“\n\nDie Stiftung erhält ihre Unterlagen zurück. Beaumont wird erklären müssen, warum er so lange weggesehen hat.'],
 late:['Als Lestrade eintrifft, ist Rook fort. Die Kasse wurde um Viertel vor elf geschlossen, wie angekündigt. Doch die Durchschläge, die Schlüsselausgabe und der Lieferzettel lassen sich nicht mitnehmen oder umschreiben: Sie haben sie gesichert.','Clara ist gerettet. Lestrade veranlasst die Fahndung. Sie haben den Fall bewiesen, aber dem Täter einen Vorsprung gelassen. Watson stellt zwei Tassen auf den Tisch. „Eine späte Wahrheit bleibt eine Wahrheit. Ihr Preis ist nur höher.“'],
 lateUnrescued:['Ihre Beweise reichen aus, Rook zu benennen, doch er hat das Theater bereits verlassen. Sie haben dem Nachweis mehr Aufmerksamkeit geschenkt als der Suche nach Clara.','Die Polizei durchsucht daraufhin jede Kammer des Hauses und findet Clara unter der Bühne. Sie lebt, braucht aber länger ärztliche Betreuung. Lestrade fahndet nach Rook. Sie nehmen die Verantwortung für die verlorene Zeit an.'],
 proofOnly:['Die Unterlagen belasten Rook schwer. Lestrade nimmt ihn fest, während Sie Ihre Beweise erläutern. Erst danach lässt die Polizei das ganze Theater durchsuchen.','Clara wird aus der Wartungskammer geholt. Sie lebt. Watson geht sofort zu ihr und sagt eine Weile nichts zu Ihnen. Der Täter ist gefasst; dass ihre Rettung warten musste, bleibt Teil dieses Abends.'],
 wrong:['Lestrade handelt auf Ihre Beschuldigung hin. Doch die anschließende Überprüfung hält ihr nicht stand. Die verdächtige Person lässt sich nicht mit Zugang, Zeitpunkt und Abrechnung verbinden. Sie haben einen Verdacht als Gewissheit ausgegeben.','Die falsche Festnahme kostet den Ermittlungen Zeit und Glaubwürdigkeit. '+(s.flags.rescued?'Clara ist durch Ihre frühere Hilfe immerhin in Sicherheit.':'Eine vollständige Durchsuchung klärt später Claras Aufenthaltsort.')+' Victor Rook ist inzwischen verschwunden. In Ihrem Bericht streichen Sie nichts aus: Auch ein Irrtum muss nachvollziehbar bleiben.'],
 unsupported:['Rook hört Ihre Beschuldigung an und fordert Beweise. Einzelne verdächtige Umstände reichen Lestrade nicht. Ohne zusammenhängendes Alibi-Gegenargument und Motiv kann er ihn nicht festhalten.','Rook verlässt das Theater. Der Fall bleibt offen. '+(s.flags.rescued?'Clara ist wenigstens in Sicherheit.':'Bei der anschließenden Durchsuchung findet die Polizei Clara. Watson kümmert sich um sie.')+' Sie wissen, dass ein richtiger Verdacht noch keine abgeschlossene Ermittlung ist.'],
 rescue:['Sie übergeben Ihre bisherigen Notizen an Lestrade und bestehen darauf, keine voreilige Beschuldigung zu erheben. Clara wird ärztlich versorgt. Für sie ist dieser Abend vorbei.','Für die Ermittlungen ist er es nicht. Rook kann gehen, solange keine belastbare Beweiskette vorliegt. Sie haben einen Menschen gerettet und den Fall bewusst offengelassen.'],
 unfinished:['Sie geben den Fall mit Ihren bisherigen Notizen an Scotland Yard ab. Lestrade ordnet eine vollständige Durchsuchung an. Erst dabei wird Clara unter der Bühne gefunden.','Watson bleibt bei ihr. Der Täter ist fort, die Ermittlung offen. Ihr Bericht enthält keine erfundene Lösung – aber die Frage, welchen gesicherten Spuren Sie hätten früher folgen können.']
};return [...(tails[s.ending]||tails.unfinished),'Drei Tage später liegt ein Brief in der Baker Street. Keine Drohung, keine Unterschrift. Nur eine Frage: „Wer gab Rook die zweite Abrechnung?“\n\nUnter der Zeile steht ein Zeichen: V–17. Sie legen den Brief in eine neue Mappe. Dieser Fall ist abgeschlossen. Ein anderer beginnt.'];}
export const END_TITLES={complete:'Die letzte Vorstellung',late:'Die Wahrheit kommt zu spät',lateUnrescued:'Der Preis der verlorenen Zeit',proofOnly:'Ein Täter. Eine offene Schuld.',wrong:'Die falsche Gewissheit',unsupported:'Ein Verdacht ist kein Beweis',rescue:'Gerettet. Noch nicht aufgeklärt.',unfinished:'Eine unvollendete Akte'};
